from behave import given, when, then
from selenium import webdriver
from selenium.webdriver.common.by import By
from selenium.webdriver.support.ui import WebDriverWait
from selenium.webdriver.support import expected_conditions as EC
import time

file_path = "index.html"

@given("the Notes App page is loaded")
def step_given_notes_app_page_loaded(context):
    context.driver = webdriver.Chrome()
    context.driver.get(f"file://index.html")
    time.sleep(1)  # Allow time for the page to load

@when("the user clicks the 'Add note' button with data-testid 'add-note-button'")
def step_when_user_clicks_add_note_button(context):
    add_note_button = WebDriverWait(context.driver, 10).until(
        EC.element_to_be_clickable((By.CSS_SELECTOR, "[data-testid='add-note-button']"))
    )
    add_note_button.click()
    time.sleep(1)  # Allow time for the note to be added

@then("a new note is displayed on the page")
def step_then_new_note_displayed(context):
    notes = context.driver.find_elements(By.CSS_SELECTOR, ".note")
    assert len(notes) > 0, "No new note was displayed on the page"

@then("the new note contains an empty textarea with data-testid 'note-textarea'")
def step_then_note_contains_empty_textarea(context):
    textarea = context.driver.find_element(By.CSS_SELECTOR, "[data-testid='note-textarea']")
    assert textarea.get_attribute("value") == "", "The textarea is not empty"

@then("the textarea is visible")
def step_then_textarea_is_visible(context):
    textarea = context.driver.find_element(By.CSS_SELECTOR, "[data-testid='note-textarea']")
    assert textarea.is_displayed(), "The textarea is not visible"

def after_scenario(context, scenario):
    context.driver.quit()
